mapper.select:
SELECT id, order_id, user_id, product_id, product_name, total_amount, order_status, pay_url, create_time, update_time
FROM orders
WHERE order_id = #{orderId}

mapper.update:
UPDATE orders
SET order_status = #{orderStatus}, update_time = NOW()
WHERE order_id = #{orderId}

UPDATE orders
SET pay_url = #{payUrl}, update_time = NOW()
WHERE order_id = #{orderId}
